<?php
 if ( ! defined( 'ABSPATH' ) ) { exit; } require_once __DIR__ . '/class-mixer-all.php'; class HVM_Widget_JoiningCTA extends HVM_Widget_Base { public function get_name() { return 'hvm_joining_cta'; } public function get_title() { return 'Mixer Joining CTA'; } public function get_icon() { return 'eicon-button'; } protected function register_controls() { $cm = '\Elementor\Controls_Manager'; $this->start_controls_section( 'jcta_content', array( 'label' => 'Button', 'tab' => constant( "$cm::TAB_CONTENT" ) ) ); $this->add_control( 'cta_text', array( 'label' => 'Text', 'type' => constant( "$cm::TEXT" ), 'default' => 'Request to Join', ) ); $this->add_control( 'cta_variant', array( 'label' => 'Style', 'type' => constant( "$cm::SELECT" ), 'default' => 'dark', 'options' => array( 'dark' => 'Dark (navy)', 'light' => 'Light' ), ) ); $this->add_responsive_control( 'cta_align', array( 'label' => 'Alignment', 'type' => constant( "$cm::CHOOSE" ), 'default' => 'left', 'options' => array( 'left' => array( 'title' => 'Left', 'icon' => 'eicon-text-align-left' ), 'center' => array( 'title' => 'Center', 'icon' => 'eicon-text-align-center' ), 'right' => array( 'title' => 'Right', 'icon' => 'eicon-text-align-right' ), ), 'selectors' => array( '{{WRAPPER}} .hvm-joincta' => 'text-align:{{VALUE}};' ), ) ); $this->add_control( 'cta_note', array( 'type' => constant( "$cm::RAW_HTML" ), 'raw' => 'Href = this event\'s <strong>Request-to-Join Link</strong>; if a <strong>Luma Event ID</strong> is set it opens the Luma checkout.', 'content_classes' => 'elementor-descriptor', ) ); $this->end_controls_section(); } protected function render() { $s = $this->get_settings_for_display(); $text = ( isset( $s['cta_text'] ) && '' !== trim( (string) $s['cta_text'] ) ) ? $s['cta_text'] : 'Request to Join'; $variant = ( 'light' === ( $s['cta_variant'] ?? 'dark' ) ) ? 'light' : 'dark'; echo '<div class="hvm-joincta">'; $this->render_join_cta( $text, $variant, 'hvm-joincta-btn' ); echo '</div>'; } } add_filter( 'hvm_mixer_widget_classes', function ( $classes ) { $classes[] = 'HVM_Widget_JoiningCTA'; return $classes; } ); 